BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(30);
SELECT ok(to_regclass('app_private.admission_principal_approvals') IS NOT NULL,'private immutable Principal APPROVE source created');
SELECT ok((SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid='app_private.admission_principal_approvals'::regclass),'new approval source forced RLS');
SELECT ok((SELECT count(*)=1 FROM pg_policies WHERE schemaname='app_private' AND tablename='admission_principal_approvals' AND policyname='db03_principal_approval_storage_owner'),'schema owner only policy');
SELECT ok(NOT has_table_privilege('authenticated','app_private.admission_principal_approvals','INSERT'),'client cannot insert approvals');
SELECT ok(NOT has_table_privilege('service_role','app_private.admission_principal_approvals','INSERT'),'service role cannot insert approvals');
SELECT ok(NOT has_table_privilege('schoolos_workflow_executor','app_private.admission_principal_approvals','INSERT'),'workflow cannot insert approvals');
SELECT ok(NOT has_table_privilege('schoolos_student_executor','app_private.admission_principal_approvals','UPDATE'),'Student executor cannot modify approvals');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgname='db03_principal_approval_mutation_disabled' AND tgenabled='O'),'approval row mutation denied');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgname='db03_principal_approval_no_truncate' AND tgenabled='O'),'approval TRUNCATE denied');
SELECT ok((SELECT contype='u' FROM pg_constraint WHERE conname='db03_approval_snapshot_forward_receipt_source'),'snapshot scope with receipt source unique');
SELECT ok((SELECT cardinality(conkey)=6 FROM pg_constraint WHERE conname='db03_approval_snapshot_forward_receipt_source'),'snapshot exact source includes six columns');
SELECT ok((SELECT contype='u' FROM pg_constraint WHERE conname='db03_approval_handoff_consumed_source'),'handoff state composite source key');
SELECT ok((SELECT cardinality(conkey)=3 FROM pg_constraint WHERE conname='db03_approval_handoff_consumed_source'),'handoff state source includes three columns');
SELECT ok((SELECT contype='u' AND cardinality(conkey)=8 FROM pg_constraint WHERE conname='db03_principal_approval_matching_source'),'approval exact 8-column source key');
SELECT ok((SELECT contype='f' AND cardinality(conkey)=6 FROM pg_constraint WHERE conname='db03_principal_approval_matching_snapshot'),'approval exact policy/forward/version/receipt link');
SELECT ok((SELECT NOT condeferrable FROM pg_constraint WHERE conname='db03_principal_approval_matching_snapshot'),'snapshot provenance checked immediately');
SELECT ok((SELECT contype='f' AND cardinality(conkey)=3 FROM pg_constraint WHERE conname='db03_principal_approval_requires_consumed_handoff'),'approval requires corresponding consumed handoff');
SELECT ok((SELECT condeferrable AND condeferred FROM pg_constraint WHERE conname='db03_principal_approval_requires_consumed_handoff'),'approval consumed handoff FK deferred to commit');
SELECT ok((SELECT confupdtype='a' AND confdeltype='a' FROM pg_constraint WHERE conname='db03_principal_approval_requires_consumed_handoff'),'approval cyclic FK NO ACTION');
SELECT ok((SELECT contype='f' AND cardinality(conkey)=8 FROM pg_constraint WHERE conname='db03_handoff_exact_principal_approval'),'handoff binds exact approval version and receipt');
SELECT ok((SELECT condeferrable AND condeferred FROM pg_constraint WHERE conname='db03_handoff_exact_principal_approval'),'handoff reciprocal approval FK deferred to commit');
SELECT ok((SELECT attnotnull FROM pg_attribute WHERE attrelid='app_private.admission_student_handoffs'::regclass AND attname='principal_approval_id'),'handoff approval ID is mandatory');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_policy_snapshot_same_application_version'),'prior P45 snapshot lineage retained');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_policy_snapshot_exact_forward'),'P46B-1 forward lineage retained');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgname='db03_policy_snapshot_mutation_disabled' AND tgenabled='O'),'P44 policy snapshot writes remain disabled');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgname='db03_handoff_mutation_disabled' AND tgenabled='O'),'P38 Student handoff writes remain disabled');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgname='db03_number_allocations_mutation_disabled' AND tgenabled='O'),'P41 number allocations remain disabled');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_unsubmitted_policy_null'),'S5 unsubmitted policy projection unchanged');
SELECT ok((SELECT count(*)=0 FROM app_private.admission_principal_approvals),'no real approval records installed');
SELECT ok((SELECT count(*)=0 FROM app_private.admission_student_handoffs),'no Student handoffs installed');
SELECT * FROM finish();
ROLLBACK;
